mapper.sql:
WHERE 1 = 1

    AND t.user_id = #{query.userId}


    AND t.username ILIKE CONCAT('%', #{query.username}, '%')


    AND (t.session_id = #{query.sessionId} OR t.python_session_id = #{query.sessionId})


    AND t.request_id = #{query.requestId}


    AND t.business_type = #{query.businessType}


    AND t.entrypoint = #{query.entrypoint}


    AND t.status = #{query.status}


    AND t.started_at >= #{query.startedFrom}


    AND t.started_at <= #{query.startedTo}


    AND EXISTS (
        SELECT 1
        FROM t_ai_llm_call pc
        WHERE pc.trace_id = t.id
          AND pc.provider = #{query.provider}
    )


    AND EXISTS (
        SELECT 1
        FROM t_ai_llm_call mc
        WHERE mc.trace_id = t.id
          AND mc.model = #{query.model}
    )

mapper.select:
SELECT id AS call_id, trace_id, prompt_text, response_text
FROM t_ai_llm_call
WHERE id = #{callId}
